code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((color,cells))
    # The reference is the conspicuous L-shaped line object; recolor a straight
    # segment matching one arm of that reference.
    refs=[]
    for color,cells in comps:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        if (r1-r0+1)>=4 and (c1-c0+1)>=4:
            s=set(cells)
            for corner in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
                # long, one-cell-thick perpendicular arms meeting at a corner
                vert={(r,corner[1]) for r in range(r0,r1+1)}
                horiz={(corner[0],c) for c in range(c0,c1+1)}
                if vert|horiz <= s and len(s - (vert|horiz)) <= 1:
                    refs.append((color,s))
                    break
    out=[row[:] for row in grid]
    if not refs:
        return out
    refcolor, refcells=max(refs,key=lambda z:len(z[1]))
    candidates=[]
    for color,cells in comps:
        s=set(cells)
        if color==refcolor or len(s)<2:
            continue
        rs=[r for r,c in s]; cs=[c for r,c in s]
        # A straight object that is a segment of the reference L.
        if len(set(rs))==1 or len(set(cs))==1:
            if s <= refcells:
                candidates.append((len(s),cells))
    if candidates:
        _,cells=max(candidates,key=lambda z:z[0])
        for r,c in cells:
            out[r][c]=refcolor
    return out
