code3='''from collections import deque

def _norm(cells, flip=False, rot=0):
    pts=[]
    for r,c in cells:
        x,y=r,c
        if flip: y=-y
        for _ in range(rot): x,y=y,-x
        pts.append((x,y))
    mr=min(x for x,y in pts); mc=min(y for x,y in pts)
    return frozenset((x-mr,y-mc) for x,y in pts)

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in {v for row in grid for v in row}}
    bg=max(counts,key=counts.get)
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==v:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((v,cells))
    # Find the large L-shaped reference object.
    refs=[]
    for color,cells in comps:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs); s=set(cells)
        if r1-r0+1<4 or c1-c0+1<4: continue
        for corner in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            arms={(r,corner[1]) for r in range(r0,r1+1)} | {(corner[0],c) for c in range(c0,c1+1)}
            if arms <= s and len(s-arms)<=1:
                refs.append((color,s)); break
    out=[row[:] for row in grid]
    if refs:
        refcolor,ref=max(refs,key=lambda z:len(z[1]))
        pairs=[]
        for i,(ca,a) in enumerate(comps):
            for cb,b in comps[i+1:]:
                sa={_norm(a,f,r) for f in (False,True) for r in range(4)}
                sb={_norm(b,f,r) for f in (False,True) for r in range(4)}
                if sa & sb:
                    def dist(cells):
                        return sum(r for r,c in cells)/len(cells),sum(c for r,c in cells)/len(cells)
                    ra,ca0=dist(a); rb,cb0=dist(b)
                    rr=sum(r for r,c in ref)/len(ref); rc=sum(c for r,c in ref)/len(ref)
                    da=(ra-rr)**2+(ca0-rc)**2; db=(rb-rr)**2+(cb0-rc)**2
                    pairs.append((max(da,db),a if da>db else b))
        if pairs:
            cells=max(pairs,key=lambda p:p[0])[1]
            for r,c in cells: out[r][c]=refcolor
    return out
